    "description": "针对网络曝光河北张家口康保县大白菜违规使用甲醛保鲜一事，南京众彩蔬菜市场立即开展应急排查处置。 市场白菜日均到货约150吨，货源涵盖山东、甘肃、内蒙古、河北等产区。8月22日起对场内在售、待售大白菜开展地毯式排查及抽样检测，累计检测53批次，均未检出甲醛等有害物质。 市场已全面禁止张家口康保县大白菜入场；其余产区大白菜升级为关注品种，甲醛纳入必检项目，严格执行“先检后进”，检测合格方可销售。同时督促商户落实索证索票，强化食品安全宣教，压…",
    "content": "针对网络曝光河北张家口康保县大白菜违规使用甲醛保鲜一事，南京众彩蔬菜市场立即开展应急排查处置。 市场白菜日均到货约150吨，货源涵盖山东、甘肃、内蒙古、河北等产区。8月22日起对场内在售、待售大白菜开展地毯式排查及抽样检测，累计检测53批次，均未检出甲醛等有害物质。 市场已全面禁止张家口康保县大白菜入场；其余产区大白菜升级为关注品种，甲醛纳入必检项目，严格执行“先检后进”，检测合格方可销售。同时督促商户落实索证索票，强化食品安全宣教，压实进货主体责任。 目前，市场山东、甘肃、内蒙古等地大白菜货源充足、价格平稳，请市…"
