    "content": "新华社洛杉矶8月23日电（记者高山）一场大型野火23日快速逼近地处美国内华达州、与加利福尼亚州邻近的里诺市。当地消防部门证实凶猛火势已造成6人受伤，迫使约4.2万名当地居民紧急撤离，另有4.5万人处于撤离警告区。 消防官员在23日的记者会上表示，这场人为因素引发的野火在约24小时内过火面积已扩大至约53平方公里，火势目前处于失控状态。约有800名消防应急人员奋战在火场周边，包括3名消防应急人员在内的6人受伤。 内华达州州长乔·隆巴尔多宣布里诺市所在的沃肖县进入紧急状态，并下令动员内华达州国民警卫队。当地目前有约1万…"
