    "content": "23/08/2026 - 22:31 南京信息工程大学张慧明等人于2026年8月20日在《科学》（Science）杂志发表研究，指出中国大规模扩张太阳能光伏项目导致耕地与草地减少，引发鸟类多样性下降。该研究揭示了减碳和生态保护之间的“绿色困境”，并建议未来需更谨慎评估光伏项目选址。 他表示：“我们的信息并非要放慢向可再生能源转型的步伐，而是要确保太阳能的发展更加重视环境问题。” 这位研究人员及其同事观察了中国的太阳能扩张政策、气候模式、土地利用、鸟类种群等因素。科学家们得出结论：太阳能扩张与鸟类多样性的下降密切相关…"
