    "content": "23/08/2026 - 22:09 美国芯片大厂英伟达（Nvidia）计划将一项本周敲定、规模达60亿美元的协议，用于打造全球最强大的开放权重人工智能模型之一，盼在快速成长的开放模型市场，与中国人工智能企业深度求索（DeepSeek）等竞争。 这项计划显示，英伟达正从人工智能芯片和算力供应商，进一步向人工智能模型开发领域延伸。根据美国《华尔街日报》（Wall Street Journal）等媒体报导，英伟达希望利用自身在人工智能运算基础设施方面的优势，建立具备全球顶尖性能的开放权重模型，强化美国在这一领域的竞争力…"
