    "description": "23/08/2026 - 19:56 中国载人航天机构表示，经过“全面评估”后认定，这项原计划使用长征五号运载火箭发射“嫦娥七号”月球探测器的任务“不具备发射条件，无法在今年计划的发射窗口期内实施”。 该机构补充称，推迟发射的决定是“基于审慎、可靠及确保任务绝对成功的原则”作出的，但未透露具体是哪些条件未达标，也未说明重新安排发射的具体时间。 据媒体报道，这项旨在搜寻月球南极水资源的探测任务原定于上周末或周一启程。上周，该机构曾表示，探…",
    "content": "23/08/2026 - 19:56 中国载人航天机构表示，经过“全面评估”后认定，这项原计划使用长征五号运载火箭发射“嫦娥七号”月球探测器的任务“不具备发射条件，无法在今年计划的发射窗口期内实施”。 该机构补充称，推迟发射的决定是“基于审慎、可靠及确保任务绝对成功的原则”作出的，但未透露具体是哪些条件未达标，也未说明重新安排发射的具体时间。 据媒体报道，这项旨在搜寻月球南极水资源的探测任务原定于上周末或周一启程。上周，该机构曾表示，探测器和运载火箭已转运至位于海南省南部的文昌航天发射场发射区。 截至周三，发射场及…"
