    "content": "缘起 用 Kimi Code 写代码的人都懂这种感觉：正写得顺手，突然被限流，打开一看 5 小时窗口早就烧完了——但网页上查额度这件事，每次都要打断心流。 社区里有个 macOS 上的好工具 KimiCodeBar （@xifandev 的作品），常驻菜单栏看额度。但 Windows 用户一直没有对应的版本。于是经原作者认可，我做了个 Windows 社区移植版，两仓库分治、各自独立发版。 是什么 一个常驻系统托盘的小工具： 左键点托盘图标 → 弹出用量面板：7 天窗口 + 5 小时窗口的已用百分比、剩余量、重置倒…"
