    "content": "新华社德黑兰8月23日消息，据伊朗塔斯尼姆通讯社23日报道，伊朗伊斯兰革命卫队发言人穆赫比当天表示，伊朗针对美国各种敌对行动均已制定应对方案，包括应对经济施压。 穆赫比在伊朗北部城市卡拉季举行的新闻发布会上说，美国日前宣布对伊朗发动“最严厉的经济战”，这一表态实际上表明美方在军事领域未能实现目标。他说，美国对伊朗实施经济制裁已有47年，当前有关“经济战”的表态意在对伊朗民众施加心理影响。 穆赫比表示，伊方已制定方案以应对“经济战”造成的不利影响，并将继续“在美国眼皮底下”同其他国家开展经济往来、绕过美国限制。他称，…"
