    "content": "新华社呼和浩特8月23日电 题：2026绿色算力（人工智能）大会：算得快、用得省 新华社记者安路蒙、王雪冰 从建得快转向用得好，从拼规模转向拼能效……8月22日，2026绿色算力（人工智能）大会在内蒙古自治区呼和浩特市召开，透过这场大会，一条算力发展路径愈发清晰：绿色算力，既要算得快，更要用得省。 绿色算力并非绿电加服务器那么简单。粤港澳大湾区大数据研究院名誉理事长杜平在会上给出三层理解：基础层是绿电与服务器的结合；技术层是软硬件的适配与协同交互；增值服务层是算力、电力、数据三大市场交叉融合的新业态。“绿色算力是一…"
