    "author": "hashkitly",
    "description": "大家好，最近做了一个 AI 图片和视频生成网站：Froging AI 。 目前支持文生视频、图生视频和 AI 图片生成，接入了 Veo 、Kling 、Seedance 、Wan 、MiniMax 等模型。主要是想解决模型太分散、来回切换麻烦的问题。 新用户送 20 积分，不用绑定信用卡，生成内容无水印。网站目前以英文为主，中文界面也在计划中。 地址： https://www.froging.ai/ 产品还在持续完善，想请大家帮忙体验一…",
    "content": "大家好，最近做了一个 AI 图片和视频生成网站：Froging AI 。 目前支持文生视频、图生视频和 AI 图片生成，接入了 Veo 、Kling 、Seedance 、Wan 、MiniMax 等模型。主要是想解决模型太分散、来回切换麻烦的问题。 新用户送 20 积分，不用绑定信用卡，生成内容无水印。网站目前以英文为主，中文界面也在计划中。 地址： https://www.froging.ai/ 产品还在持续完善，想请大家帮忙体验一下。模型选择、生成效果、价格或者操作流程方面，有任何问题都欢迎直接提。"
