    "content": "23/08/2026 - 16:10 周日（8月23日），乌克兰总统泽连斯基表示，在战争期间举行选举将给乌克兰带来危险。此前他曾遭解职的前国防部长呼吁为举行选举铺平道路，引发争议。 泽连斯基说：“我认为，在这样的战争中，举行选举本身就是一个巨大的风险。” 他进而强调：“现在举行选举，就像一场会撕裂乌克兰的海啸。”他本人于2019年当选总统。 此前，乌克兰举行选举的问题已经被俄罗斯和美国总统提及，但戒严状态自2022年2月俄罗斯对乌克兰发动全面入侵以来一直持续，而根据现行戒严法，乌克兰目前无法组织选举。 泽连斯基对记…"
