    "description": "中新网广西崇左8月23日电(涂丽莎 陈沿佑)秋日时节，广西崇左市扶绥县渠黎镇甜蜜之光现代甘蔗产业园满目青绿。桂糖44号、云蔗081609、桂糖76号、中糖3号、中辐1号等甘蔗品种长势喜人，大多数蔗株高度超3米。园区采用的多品种轮作、分区种植方式，保障了这片土地长期稳产与生态韧性。",
    "content": "中新网广西崇左8月23日电(涂丽莎 陈沿佑)秋日时节，广西崇左市扶绥县渠黎镇甜蜜之光现代甘蔗产业园满目青绿。桂糖44号、云蔗081609、桂糖76号、中糖3号、中辐1号等甘蔗品种长势喜人，大多数蔗株高度超3米。园区采用的多品种轮作、分区种植方式，保障了这片土地长期稳产与生态韧性。"
