    "content": "出发，不负美好时光；旅行，共赴心中山海。 这个暑期，游客热情高涨，文旅热力十足。从奔赴“宝藏小城”的“小确幸”，到流连沉浸式体验的氛围感；从上山下海避暑，到漫游栖居度假……人们饱览大好河山，“花样”文旅点亮夏日经济。 习近平总书记指出，文旅融合促进了经济发展，文旅产业要走一条持续、健康的发展之路。 细观今夏文旅图景，旅游向多样化、个性化、品质化发展趋势愈加明晰。在融合发展、守正创新中，旅游不断丰富人民美好生活的成色，绘就高质量发展的诗和远方。 “奔县游”受到青睐 夏日风情好，侗寨引客来。 寨门迎宾、鼓楼传歌、蓝靛染…"
