    "description": "（来源：麻省理工科技评论） 今年晚些时候，美国公司 Reflect Orbital 计划发射一颗名为 Eärendil-1 的测试卫星。进入轨道后，卫星将展开一面 18 米 × 18 米的反射镜。这颗卫星主要用于验证公司的长期计划。Reflect Orbital 希望未来最多发射 5 万颗更大的卫星，每颗配备 54 米 × 54 米的反射镜，在需要的时候把阳光反射到地球。 至于为什么要这么做，目前外界仍有不少疑问。Reflect Orb…",
    "content": "（来源：麻省理工科技评论） 今年晚些时候，美国公司 Reflect Orbital 计划发射一颗名为 Eärendil-1 的测试卫星。进入轨道后，卫星将展开一面 18 米 × 18 米的反射镜。这颗卫星主要用于验证公司的长期计划。Reflect Orbital 希望未来最多发射 5 万颗更大的卫星，每颗配备 54 米 × 54 米的反射镜，在需要的时候把阳光反射到地球。 至于为什么要这么做，目前外界仍有不少疑问。Reflect Orbital 表示，这项技术的目标是延长特定地区的日照时间，应用场景包括为太阳能电池…"
