    "description": "新华社昆明8月23日电 记者23日晚从云南省凤庆县人民政府新闻办公室获悉，8月23日凌晨1时至8时，凤庆县凤山镇遭遇持续性强降雨天气。凤山镇安石村累计降雨量达101.8毫米，诱发泥石流灾害，造成2人失联。凤山镇水箐村累计降雨量达106毫米，诱发滑坡灾害，造成4人失联。 灾害发生后，凤庆县迅速启动Ⅲ级应急响应，统筹调度应急、公安、消防、水务、交通、自然资源、医疗等救援力量，开展群众转移安置、气象监测预警、次生灾害防范等工作。截至8月23日…",
    "content": "新华社昆明8月23日电 记者23日晚从云南省凤庆县人民政府新闻办公室获悉，8月23日凌晨1时至8时，凤庆县凤山镇遭遇持续性强降雨天气。凤山镇安石村累计降雨量达101.8毫米，诱发泥石流灾害，造成2人失联。凤山镇水箐村累计降雨量达106毫米，诱发滑坡灾害，造成4人失联。 灾害发生后，凤庆县迅速启动Ⅲ级应急响应，统筹调度应急、公安、消防、水务、交通、自然资源、医疗等救援力量，开展群众转移安置、气象监测预警、次生灾害防范等工作。截至8月23日17时，已搜寻到水箐村2名失联人员，经医护人员确认，均已无生命体征。其余失联人员…"
