    "pub_date": "2026-08-23 20:57:23",
    "author": "杨驰",
    "description": "炎炎夏日，戏水纳凉成为不少人的休闲选择。但看似平静的野外水域，实则暗藏重重危机。水下地形复杂难测，深浅不一，常有暗礁、淤泥与水草分布。我们每个人都需提高安全防范意识，主动远离无安全保障的野外水域，不贸然下水野泳、戏水。同时，主动学习避险与科学施救知识，遇人落水不盲目下水施救，优先采取呼救、抛掷救生器材等救援方式。守住安全底线，方能尽享惬意夏日时光。 作者：杨驰、文雪仪、林彤 新华社音视频部制作",
    "content": "炎炎夏日，戏水纳凉成为不少人的休闲选择。但看似平静的野外水域，实则暗藏重重危机。水下地形复杂难测，深浅不一，常有暗礁、淤泥与水草分布。我们每个人都需提高安全防范意识，主动远离无安全保障的野外水域，不贸然下水野泳、戏水。同时，主动学习避险与科学施救知识，遇人落水不盲目下水施救，优先采取呼救、抛掷救生器材等救援方式。守住安全底线，方能尽享惬意夏日时光。 作者：杨驰、文雪仪、林彤 新华社音视频部制作 &nbsp;"
