    "content": "陕西咸阳的面食文化源远流长，作为汉唐京畿要地的三原县，更是流传了许多风味独特且吃法讲究的特色面食。一起跟随镜头“打卡”贵妃饺、疙瘩面、泡泡油糕等传统小吃，感受美味背后的地域民俗。 作者：吴斯洋、周季、刘子康 新华社音视频部制作"
