    "description": "新华社德黑兰8月23日电（记者陈霄 沙达提）据伊朗伊斯兰共和国通讯社23日报道，伊朗总统佩泽希齐扬22日晚表示，伊朗应以理性方式，使国家摆脱“既非战争、也非和平”状态。 据报道，佩泽希齐扬在首都德黑兰出席“医生日”纪念活动时说，伊朗“不可能永远依靠战争走下去。总有一天必须作出决定，使国家摆脱‘既非战争、也非和平’的状态”，在战争或“非战非和”状态下伊朗难以吸引投资。他还提及已故最高领袖哈梅内伊也曾明确表示伊朗必须摆脱“非战非和”状态。 …",
