    "content": "23/08/2026 - 13:23 中国有关地方部门周日（8月23日）向法新社证实，中国知名喜剧演员郭德纲因在演出期间未经授权，以讽刺方式改编一首爱国歌曲的歌词，目前正受到调查。 据本台此前报道， 8月12日，经网友爆料，郭德纲今年7月在武汉演出中即兴改编红歌《弹起我心爱的土琵琶》，因改编内容未经报备涉嫌违规，武汉市文旅局已于8月11日正式立案调查 。 据《澎湃新闻》报道，郭德纲在舞台上将原歌词“微山湖静悄悄”等内容改成了“紫禁城静悄悄”等，并接上一串佛号和密咒口诀的即兴改词，随后被部分观众及网民举报。该媒体援引…"
