    "description": "8月22日至23日，2026浙江建德17℃新安江“夏日冬泳”轻极限运动挑战赛在浙江省建德市启幕。来自浙江、上海、安徽、福建、江苏等8个省市的100余支代表队、1000多名游泳健儿齐聚新安江畔，跃入常年保持17℃的清澈江流，体验“水上骄阳似火、水下冰凉刺骨”的极致反差。 新华社音视频部制作",
